   SHRIKHA FINSERV — HOME LOAN PAGE & ADVANCED EMI CALCULATOR STYLES
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. Page Layout & Base Container
   -------------------------------------------------------------------------- */
.home-loan-page-wrapper {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: var(--color-bg);
}

.hl-hero-section {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 50%, var(--color-primary-light) 100%);
}

.hl-calculator-section {
  padding: 5rem 0 3rem 0;
  background-color: var(--color-bg);
}

/* --------------------------------------------------------------------------
   2. Home Loan Live Results & Donut Chart
   -------------------------------------------------------------------------- */
.hl-results-card {
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
  height: 100%;
}

.hl-results-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.hl-results-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-secondary);
  background-color: var(--color-secondary-tint);
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full);
}

.hl-tenure-tag {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

/* Monthly EMI Card (Prominent navy blue figure) */
.hl-monthly-emi-highlight {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: #FFFFFF;
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  text-align: center;
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
}

.hl-monthly-emi-highlight::after {
  content: '';
  position: absolute;
  top: -20px;
  right: -20px;
  width: 110px;
  height: 110px;
  background: radial-gradient(circle, rgba(214, 173, 96, 0.25) 0%, rgba(214, 173, 96, 0) 70%);
  border-radius: 50%;
}

.hl-emi-caption {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent-light);
  margin-bottom: 0.5rem;
}

.hl-emi-figure-wrap {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 0.65rem;
}

.hl-emi-large-figure {
  font-size: clamp(2.2rem, 3.5vw, 3rem);
  font-weight: 800;
  color: #FFFFFF;
  letter-spacing: -0.02em;
}

.hl-emi-freq {
  font-size: 1.05rem;
  font-weight: 500;
  color: #CBD5E1;
}

.hl-emi-sub-params {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  font-size: 0.825rem;
  color: #94A3B8;
}

.hl-emi-sub-params span {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

.param-sep {
  color: rgba(255, 255, 255, 0.2);
}

/* Donut Chart */
.hl-chart-section {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.hl-chart-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--color-primary);
  margin: 0;
}

.hl-chart-wrapper {
  display: flex;
  align-items: center;
  justify-content: space-around;
  gap: 1.5rem;
}

.hl-chart-svg-container {
  position: relative;
  width: 180px;
  height: 180px;
  flex-shrink: 0;
}

.hl-donut-svg {
  transform: rotate(0deg);
  overflow: visible;
}

.hl-circle-principal,
.hl-circle-interest {
  transition: stroke-dasharray 0.4s ease, stroke-dashoffset 0.4s ease;
}

.hl-chart-center-content {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  display: flex;
  flex-direction: column;
  pointer-events: none;
  max-width: 110px;
}

.hl-chart-center-label {
  font-size: 0.725rem;
  text-transform: uppercase;
  color: var(--color-text-muted);
  font-weight: 600;
}

.hl-chart-center-value {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--color-primary);
  word-break: keep-all;
}

.hl-chart-legend {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  flex-grow: 1;
}

.hl-legend-row {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
}

.hl-legend-dot {
  width: 12px;
  height: 12px;
  border-radius: 4px;
  margin-top: 0.25rem;
  flex-shrink: 0;
}

.hl-legend-meta {
  display: flex;
  flex-direction: column;
}

.hl-legend-title {
  font-size: 0.775rem;
  color: var(--color-text-muted);
}

.hl-legend-numbers {
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
}

.hl-legend-amount {
  font-size: 0.95rem;
  color: var(--color-primary);
}

.hl-legend-badge {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

.hl-legend-badge.gold-badge {
  color: var(--color-accent-dark);
}

/* Metric Cards Grid (6 items) */
.hl-summary-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.hl-metric-card {
  background: #FFFFFF;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  transition: transform var(--transition-fast);
}

.hl-metric-card:hover {
  transform: translateY(-2px);
}

.hl-metric-card-primary {
  background: var(--color-secondary-tint);
  border-color: rgba(30, 77, 140, 0.2);
}

.hl-metric-label {
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.hl-metric-val {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--color-primary);
}

.text-gold {
  color: var(--color-accent-dark) !important;
}

.text-navy {
  color: var(--color-secondary) !important;
}

/* Action Area */
.hl-results-action-area {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.btn-proceed-hl-enquiry {
  width: 100%;
  justify-content: center;
  font-size: 1.05rem;
  font-weight: 700;
  padding: 0.85rem 1.5rem;
  box-shadow: var(--shadow-gold);
}

.hl-action-note {
  font-size: 0.75rem;
  text-align: center;
  color: var(--color-text-muted);
  margin: 0;
}

.hl-compliance-note {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  font-size: 0.75rem;
  color: var(--color-text-light);
  line-height: 1.4;
  padding-top: 0.5rem;
  border-top: 1px solid var(--color-border-subtle);
}

.hl-compliance-note .note-icon {
  color: var(--color-text-muted);
  flex-shrink: 0;
  margin-top: 0.1rem;
}

/* --------------------------------------------------------------------------
   3. Property Planning Assistant ("Plan Your Home Purchase")
   -------------------------------------------------------------------------- */
.property-planning-card {
  margin-top: 2.5rem;
  background-color: #FFFFFF;
  border-radius: var(--radius-xl);
  border: 1.5px solid rgba(214, 173, 96, 0.4);
  box-shadow: var(--shadow-lg);
  padding: 2.25rem;
  position: relative;
  overflow: hidden;
}

.property-planning-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--color-secondary) 0%, var(--color-accent) 50%, var(--color-secondary) 100%);
}

.planning-header {
  margin-bottom: 2rem;
}

.planning-title-box {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 0.5rem;
}

.planning-icon-wrapper {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent-subtle);
  color: var(--color-accent-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(214, 173, 96, 0.4);
}

.planning-tag {
  margin-bottom: 0.25rem !important;
}

.planning-title {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--color-primary);
  margin: 0;
}

.planning-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin: 0;
  max-width: 750px;
}

.planning-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1.1fr;
  gap: 1.75rem;
  align-items: flex-start;
}

.planning-field {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.planning-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-primary);
}

.planning-live-badge {
  font-size: 0.775rem;
  font-weight: 700;
  color: var(--color-secondary);
  background: var(--color-secondary-tint);
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-full);
}

.planning-result-box {
  background: linear-gradient(135deg, #F8FAFC 0%, #EEF4FC 100%);
  border: 1px solid #BFDBFE;
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.planning-result-meta {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.result-label {
  font-size: 0.775rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-secondary);
}

.result-figure {
  font-size: 1.85rem;
  font-weight: 800;
  color: var(--color-primary);
  letter-spacing: -0.01em;
}

.result-formula {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

.btn-transfer-loan {
  width: 100%;
  justify-content: center;
  gap: 0.5rem;
  font-size: 0.95rem;
  font-weight: 700;
  padding: 0.75rem 1.25rem;
}

.planning-disclaimer-strip {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin-top: 1.5rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--color-border);
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.5;
}

.planning-disclaimer-strip .info-icon {
  color: var(--color-accent-dark);
  flex-shrink: 0;
}

/* --------------------------------------------------------------------------
   4. Enquiry Section & Additional Elements
   -------------------------------------------------------------------------- */
.hl-enquiry-section {
  padding: 5rem 0;
  background-color: #FFFFFF;
}

.hl-why-us-section {
  padding: 5rem 0;
}

.hl-how-it-works-section {
  padding: 5rem 0;
  background-color: var(--color-bg);
}

.hl-faq-section {
  padding: 5rem 0;
}

.hl-disclaimer-section {
  padding: 3rem 0 5rem 0;
  background-color: var(--color-bg);
}

.hl-disclaimer-card {
  border-left-color: var(--color-secondary) !important;
}

/* --------------------------------------------------------------------------
   5. Responsive Breakpoints
   -------------------------------------------------------------------------- */
@media (max-width: 1024px) {
  .planning-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .hl-summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .hl-summary-grid {
    grid-template-columns: 1fr;
  }

  .property-planning-card {
    padding: 1.5rem;
  }

  .hl-chart-wrapper {
    flex-direction: column;
  }
}
