t-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--color-secondary);\n  background-color: var(--color-secondary-tint);\n  padding: 0.25rem 0.65rem;\n  border-radius: var(--radius-full);\n}\n\n.hl-tenure-tag {\n  font-size: 0.8125rem;\n  font-weight: 600;\n  color: var(--color-text-muted);\n}\n\n/* Monthly EMI Card (Prominent navy blue figure) */\n.hl-monthly-emi-highlight {\n  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);\n  color: #FFFFFF;\n  border-radius: var(--radius-lg);\n  padding: 1.75rem;\n  text-align: center;\n  box-shadow: var(--shadow-md);\n  position: relative;\n  overflow: hidden;\n}\n\n.hl-monthly-emi-highlight::after {\n  content: '';\n  position: absolute;\n  top: -20px;\n  right: -20px;\n  width: 110px;\n  height: 110px;\n  background: radial-gradient(circle, rgba(214, 173, 96, 0.25) 0%, rgba(214, 173, 96, 0) 70%);\n  border-radius: 50%;\n}\n\n.hl-emi-caption {\n  display: block;\n  font-size: 0.85rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--color-accent-light);\n  margin-bottom: 0.5rem;\n}\n\n.hl-emi-figure-wrap {\n  display: flex;\n  align-items: baseline;\n  justify-content: center;\n  gap: 0.5rem;\n  margin-bottom: 0.65rem;\n}\n\n.hl-emi-large-figure {\n  font-size: clamp(2.2rem, 3.5vw, 3rem);\n  font-weight: 800;\n  color: #FFFFFF;\n  letter-spacing: -0.02em;\n}\n\n.hl-emi-freq {\n  font-size: 1.05rem;\n  font-weight: 500;\n  color: #CBD5E1;\n}\n\n.hl-emi-sub-params {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.6rem;\n  font-size: 0.825rem;\n  color: #94A3B8;\n}\n\n.hl-emi-sub-params span {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.25rem;\n}\n\n.param-sep {\n  color: rgba(255, 255, 255, 0.2);\n}\n\n/* Donut Chart */\n.hl-chart-section {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.hl-chart-title {\n  font-size: 0.95rem;\n  font-weight: 700;\n  color: var(--color-primary);\n  margin: 0;\n}\n\n.hl-chart-wrapper {\n  display: flex;\n  align-items: center;\n  justify-content: space-around;\n  gap: 1.5rem;\n}\n\n.hl-chart-svg-container {\n  position: relative;\n  width: 180px;\n  height: 180px;\n  flex-shrink: 0;\n}\n\n.hl-donut-svg {\n  transform: rotate(0deg);\n  overflow: visible;\n}\n\n.hl-circle-principal,\n.hl-circle-interest {\n  transition: stroke-dasharray 0.4s ease, stroke-dashoffset 0.4s ease;\n}\n\n.hl-chart-center-content {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  text-align: center;\n  display: flex;\n  flex-direction: column;\n  pointer-events: none;\n  max-width: 110px;\n}\n\n.hl-chart-center-label {\n  font-size: 0.725rem;\n  text-transform: uppercase;\n  color: var(--color-text-muted);\n  font-weight: 600;\n}\n\n.hl-chart-center-value {\n  font-size: 0.95rem;\n  font-weight: 800;\n  color: var(--color-primary);\n  word-break: keep-all;\n}\n\n.hl-chart-legend {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n  flex-grow: 1;\n}\n\n.hl-legend-row {\n  display: flex;\n  align-items: flex-start;\n  gap: 0.65rem;\n}\n\n.hl-legend-dot {\n  width: 12px;\n  height: 12px;\n  border-radius: 4px;\n  margin-top: 0.25rem;\n  flex-shrink: 0;\n}\n\n.hl-legend-meta {\n  display: flex;\n  flex-direction: column;\n}\n\n.hl-legend-title {\n  font-size: 0.775rem;\n  color: var(--color-text-muted);\n}\n\n.hl-legend-numbers {\n  display: flex;\n  align-items: baseline;\n  gap: 0.4rem;\n}\n\n.hl-legend-amount {\n  font-size: 0.95rem;\n  color: var(--color-primary);\n}\n\n.hl-legend-badge {\n  font-size: 0.75rem;\n  font-weight: 600;\n  color: var(--color-text-muted);\n}\n\n.hl-legend-badge.gold-badge {\n  color: var(--color-accent-dark);\n}\n\n/* Metric Cards Grid (6 items) */\n.hl-summary-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 0.75rem;\n}\n\n.hl-metric-card {\n  background: #FFFFFF;\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-md);\n  padding: 0.85rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.25rem;\n  transition: transform var(--transition-fast);\n}\n\n.hl-metric-card:hover {\n  transform: translateY(-2px);\n}\n\n.hl-metric-card-primary {\n  background: var(--color-secondary-tint);\n  border-color: rgba(30, 77, 140, 0.2);\n}\n\n.hl-metric-label {\n  font-size: 0.7rem;\n  font-weight: 600;\n  color: var(--color-text-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.hl-metric-val {\n  font-size: 1.05rem;\n  font-weight: 800;\n  color: var(--color-primary);\n}\n\n.text-gold {\n  color: var(--color-accent-dark) !important;\n}\n\n.text-navy {\n  color: var(--color-secondary) !important;\n}\n\n/* Action Area */\n.hl-results-action-area {\n  display: flex;\n  flex-direction: column;\n  gap: 0.5rem;\n}\n\n.btn-proceed-hl-enquiry {\n  width: 100%;\n  justify-content: center;\n  font-size: 1.05rem;\n  font-weight: 700;\n  padding: 0.85rem 1.5rem;\n  box-shadow: var(--shadow-gold);\n}\n\n.hl-action-note {\n  font-size: 0.75rem;\n  text-align: center;\n  color: var(--color-text-muted);\n  margin: 0;\n}\n\n.hl-compliance-note {\n  display: flex;\n  align-items: flex-start;\n  gap: 0.5rem;\n  font-size: 0.75rem;\n  color: var(--color-text-light);\n  line-height: 1.4;\n  padding-top: 0.5rem;\n  border-top: 1px solid var(--color-border-subtle);\n}\n\n.hl-compliance-note .note-icon {\n  color: var(--color-text-muted);\n  flex-shrink: 0;\n  margin-top: 0.1rem;\n}\n\n/* --------------------------------------------------------------------------\n   3. Property Planning Assistant (\"Plan Your Home Purchase\")\n   -------------------------------------------------------------------------- */\n.property-planning-card {\n  margin-top: 2.5rem;\n  background-color: #FFFFFF;\n  border-radius: var(--radius-xl);\n  border: 1.5px solid rgba(214, 173, 96, 0.4);\n  box-shadow: var(--shadow-lg);\n  padding: 2.25rem;\n  position: relative;\n  overflow: hidden;\n}\n\n.property-planning-card::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 4px;\n  background: linear-gradient(90deg, var(--color-secondary) 0%, var(--color-accent) 50%, var(--color-secondary) 100%);\n}\n\n.planning-header {\n  margin-bottom: 2rem;\n}\n\n.planning-title-box {\n  display: flex;\n  align-items: center;\n  gap: 1rem;\n  margin-bottom: 0.5rem;\n}\n\n.planning-icon-wrapper {\n  width: 48px;\n  height: 48px;\n  border-radius: var(--radius-md);\n  background: var(--color-accent-subtle);\n  color: var(--color-accent-dark);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: 1px solid rgba(214, 173, 96, 0.4);\n}\n\n.planning-tag {\n  margin-bottom: 0.25rem !important;\n}\n\n.planning-title {\n  font-size: 1.35rem;\n  font-weight: 800;\n  color: var(--color-primary);\n  margin: 0;\n}\n\n.planning-subtitle {\n  font-size: 0.95rem;\n  color: var(--color-text-muted);\n  margin: 0;\n  max-width: 750px;\n}\n\n.planning-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr 1.1fr;\n  gap: 1.75rem;\n  align-items: flex-start;\n}\n\n.planning-field {\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n}\n\n.planning-label {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: var(--color-primary);\n}\n\n.planning-live-badge {\n  font-size: 0.775rem;\n  font-weight: 700;\n  color: var(--color-secondary);\n  background: var(--color-secondary-tint);\n  padding: 0.15rem 0.5rem;\n  border-radius: var(--radius-full);\n}\n\n.planning-result-box {\n  background: linear-gradient(135deg, #F8FAFC 0%, #EEF4FC 100%);\n  border: 1px solid #BFDBFE;\n  border-radius: var(--radius-lg);\n  padding: 1.5rem;\n  display: flex;\n  flex-direction: column;\n  gap: 1.25rem;\n}\n\n.planning-result-meta {\n  display: flex;\n  flex-direction: column;\n  gap: 0.35rem;\n}\n\n.result-label {\n  font-size: 0.775rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--color-secondary);\n}\n\n.result-figure {\n  font-size: 1.85rem;\n  font-weight: 800;\n  color: var(--color-primary);\n  letter-spacing: -0.01em;\n}\n\n.result-formula {\n  font-size: 0.75rem;\n  color: var(--color-text-muted);\n}\n\n.btn-transfer-loan {\n  width: 100%;\n  justify-content: center;\n  gap: 0.5rem;\n  font-size: 0.95rem;\n  font-weight: 700;\n  padding: 0.75rem 1.25rem;\n}\n\n.planning-disclaimer-strip {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  margin-top: 1.5rem;\n  padding-top: 1.25rem;\n  border-top: 1px solid var(--color-border);\n  font-size: 0.8125rem;\n  color: var(--color-text-muted);\n  line-height: 1.5;\n}\n\n.planning-disclaimer-strip .info-icon {\n  color: var(--color-accent-dark);\n  flex-shrink: 0;\n}\n\n/* --------------------------------------------------------------------------\n   4. Enquiry Section & Additional Elements\n   -------------------------------------------------------------------------- */\n.hl-enquiry-section {\n  padding: 5rem 0;\n  background-color: #FFFFFF;\n}\n\n.hl-why-us-section {\n  padding: 5rem 0;\n}\n\n.hl-how-it-works-section {\n  padding: 5rem 0;\n  background-color: var(--color-bg);\n}\n\n.hl-faq-section {\n  padding: 5rem 0;\n}\n\n.hl-disclaimer-section {\n  padding: 3rem 0 5rem 0;\n  background-color: var(--color-bg);\n}\n\n.hl-disclaimer-card {\n  border-left-color: var(--color-secondary) !important;\n}\n\n/* --------------------------------------------------------------------------\n   5. Responsive Breakpoints\n   -------------------------------------------------------------------------- */\n@media (max-width: 1024px) {\n  .planning-grid {\n    grid-template-columns: 1fr;\n    gap: 1.5rem;\n  }\n\n  .hl-summary-grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n\n@media (max-width: 768px) {\n  .hl-summary-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .property-planning-card {\n    padding: 1.5rem;\n  }\n\n  .hl-chart-wrapper {\n    flex-direction: column;\n  }\n}\n"],"sourceRoot":""}]);
