___CSS_LOADER_EXPORT___.push([module.id, `/* ==========================================================================
   SHRIKHA FINSERV — DESIGN TOKENS & CSS VARIABLES
   Royal Navy + Gold Premium Theme
   ========================================================================== */

:root {
  /* Brand Color Palette */
  --color-primary: #102A43;        /* Primary Royal Navy */
  --color-primary-light: #1D3D5E;  /* Elevated Navy */
  --color-primary-dark: #0A1C2E;   /* Deepest Navy */
  --color-navy: #102A43;
  
  --color-secondary: #102A43;      /* Royal Navy */
  --color-secondary-light: #244A73;
  --color-secondary-tint: #E8EEF5;  /* Soft Navy Tint */
  
  --color-accent: #D4A84F;         /* Accent Gold */
  --color-accent-light: #E4BE6C;   /* Light Gold */
  --color-accent-dark: #B88D35;    /* Gold Hover / Deep Gold */
  --color-accent-hover: #B88D35;   /* Gold Hover */
  --color-accent-subtle: #FDF9EE;  /* Subtle Gold Tint */
  --color-gold: #D4A84F;
  --color-gold-hover: #B88D35;
  
  --color-white: #FFFFFF;
  --color-bg: #F2F5F9;             /* Page Background: Soft Grey */
  --color-bg-alt: #FFFFFF;         /* Card Background: White */
  --color-card-bg: #FFFFFF;
  --color-bg-subtle: #E8EEF5;
  
  /* Typography Colors */
  --color-text-dark: #102A43;      /* Primary Text: Dark Navy */
  --color-text-primary: #102A43;
  --color-text-muted: #526579;     /* Secondary Text */
  --color-text-secondary: #526579;
  --color-text-light: #8295A9;     /* Light Caption Text */
  --color-text-white: #FFFFFF;
  
  /* Borders and Dividers */
  --color-border: #D9E2EC;
  --color-border-subtle: #E8EEF5;
  --color-border-focus: #D4A84F;
  --color-border-accent: rgba(212, 168, 79, 0.4);

  /* Status Colors */
  --color-success: #16A34A;
  --color-success-bg: #F0FDF4;
  --color-error: #DC2626;
  --color-error-bg: #FEF2F2;
  --color-warning: #D97706;

  /* Typography */
  --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;

  /* Shadows */
  --shadow-sm: 0 1px 3px 0 rgba(16, 42, 67, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(16, 42, 67, 0.07), 0 2px 4px -2px rgba(16, 42, 67, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(16, 42, 67, 0.08), 0 4px 6px -4px rgba(16, 42, 67, 0.04);
  --shadow-xl: 0 20px 25px -5px rgba(16, 42, 67, 0.1), 0 8px 10px -6px rgba(16, 42, 67, 0.04);
  --shadow-card: 0 4px 20px rgba(16, 42, 67, 0.06);
  --shadow-card-hover: 0 16px 32px rgba(16, 42, 67, 0.12);
  --shadow-gold: 0 6px 20px rgba(212, 168, 79, 0.35);

  /* Border Radii */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-normal: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Layout Containers */
  --container-max: 1240px;
  --container-narrow: 900px;
  --header-height: 80px;
  --announcement-height: 38px;
}

@media (max-width: 768px) {
  :root {
    --header-height: 56px;
    --announcement-height: 30px;
  }
}

@media (max-width: 480px) {
  :root {
    --header-height: 50px;
    --announcement-height: 28px;
  }
}
