   SHRIKHA FINSERV — BUSINESS LOAN PAGE & EMI CALCULATOR STYLES
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. Page Layout & Hero
   -------------------------------------------------------------------------- */
.business-loan-page-wrapper {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: var(--color-bg);
}

.bl-hero-section {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 50%, var(--color-primary-light) 100%);
}

.bl-calculator-section {
  padding: 5rem 0 3rem 0;
  background-color: var(--color-bg);
}

/* --------------------------------------------------------------------------
   2. Business Loan Results & Card Accents
   -------------------------------------------------------------------------- */
.bl-monthly-emi-highlight {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
}

.four-col-summary {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.85rem;
}

@media (min-width: 540px) {
  .four-col-summary {
    grid-template-columns: repeat(2, 1fr);
  }
}

.bl-planning-icon-wrap {
  background: rgba(214, 173, 96, 0.15) !important;
  color: var(--color-accent) !important;
  border-color: rgba(214, 173, 96, 0.4) !important;
}

.bl-planning-card::before {
  background: linear-gradient(90deg, var(--color-accent) 0%, var(--color-primary) 50%, var(--color-accent) 100%) !important;
}

.bl-funding-gap-box {
  background: linear-gradient(135deg, rgba(16, 35, 63, 0.04) 0%, rgba(214, 173, 96, 0.08) 100%);
  border: 1px dashed rgba(214, 173, 96, 0.5);
}

.bl-disclaimer-card {
  border-left-color: var(--color-accent) !important;
}

/* --------------------------------------------------------------------------
   3. Responsive Adjustments
   -------------------------------------------------------------------------- */
@media (max-width: 768px) {
  .four-col-summary {
    grid-template-columns: 1fr;
  }
}
