   SHRIKHA FINSERV — CAR LOAN PAGE & EMI CALCULATOR STYLES
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. Page Layout & Hero
   -------------------------------------------------------------------------- */
.car-loan-page-wrapper {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: var(--color-bg);
}

.cl-hero-section {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 50%, var(--color-primary-light) 100%);
}

.cl-calculator-section {
  padding: 5rem 0 3rem 0;
  background-color: var(--color-bg);
}

/* --------------------------------------------------------------------------
   2. Segmented Car Type Control
   -------------------------------------------------------------------------- */
.car-type-segmented-control {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  background: #F1F5F9;
  padding: 0.35rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
}

.car-type-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.car-type-btn:hover {
  color: var(--color-primary);
}

.car-type-btn.is-active {
  background-color: #FFFFFF;
  color: var(--color-primary);
  font-weight: 700;
  box-shadow: 0 2px 6px rgba(16, 35, 63, 0.1);
  border: 1px solid rgba(214, 173, 96, 0.4);
}

/* --------------------------------------------------------------------------
   3. Car Loan Results & Card Accents
   -------------------------------------------------------------------------- */
.cl-monthly-emi-highlight {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
}

.cl-planning-icon-wrap {
  background: rgba(30, 77, 140, 0.12) !important;
  color: var(--color-secondary) !important;
  border-color: rgba(30, 77, 140, 0.3) !important;
}

.cl-planning-card::before {
  background: linear-gradient(90deg, var(--color-accent) 0%, var(--color-secondary) 50%, var(--color-accent) 100%) !important;
}

.cl-disclaimer-card {
  border-left-color: var(--color-accent) !important;
}

/* --------------------------------------------------------------------------
   4. Responsive Adjustments
   -------------------------------------------------------------------------- */
@media (max-width: 768px) {
  .car-type-segmented-control {
    grid-template-columns: 1fr;
  }
}
