  padding: 0.85rem 1.25rem;
  margin-bottom: 2rem;
  font-size: 0.9rem;
  animation: fadeIn 0.3s ease;
}

.prefill-notification-banner .banner-icon {
  color: #2563EB;
  flex-shrink: 0;
}

.enquiry-form-card {
  background: #FFFFFF;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: 2.75rem;
  box-shadow: var(--shadow-lg);
}

.form-grid-2col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.form-group-span-2 {
  grid-column: span 2;
}

.input-with-icon {
  position: relative;
  display: flex;
  align-items: center;
}

.input-icon {
  position: absolute;
  left: 1rem;
  color: var(--color-text-muted);
  pointer-events: none;
}

.textarea-icon {
  top: 1rem;
}

.input-with-icon .form-input,
.input-with-icon .form-select {
  padding-left: 2.75rem;
}

.input-with-icon .form-textarea {
  padding-left: 2.75rem;
  resize: vertical;
}

/* Radio Pill Group */
.radio-pill-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}

.radio-pill-item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background-color: #F8FAFC;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.radio-pill-item:hover {
  border-color: var(--color-secondary);
  color: var(--color-primary);
}

.radio-pill-item.is-selected {
  background-color: var(--color-secondary-tint);
  border-color: var(--color-secondary);
  color: var(--color-secondary);
  font-weight: 700;
}

/* Preferred Contact Method Pills */
.contact-methods-pill-group {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.method-pill-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.6rem 1.25rem;
  background-color: #F8FAFC;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.method-pill-item:hover {
  border-color: var(--color-secondary);
  color: var(--color-primary);
}

.method-pill-item.is-selected {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
  color: #FFFFFF;
}

.form-error-msg {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.775rem;
  color: var(--color-error);
  margin-top: 0.35rem;
  animation: fadeIn 0.2s ease;
}

.form-privacy-note {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.8rem;
  color: var(--color-text-muted);
  margin-top: 1.5rem;
  padding: 0.85rem 1rem;
  background-color: #F8FAFC;
  border-radius: var(--radius-md);
}

.shield-icon {
  color: var(--color-secondary);
  flex-shrink: 0;
}

.form-actions-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-top: 2rem;
  flex-wrap: wrap;
}

.submit-enquiry-btn {
  flex-grow: 1;
  justify-content: center;
  background: var(--color-accent) !important;
  color: var(--color-primary) !important;
  font-weight: 700 !important;
  box-shadow: 0 4px 14px rgba(212, 168, 79, 0.35) !important;
  border: none !important;
  transition: all var(--transition-fast);
}

.submit-enquiry-btn:hover {
  background: var(--color-accent-dark) !important;
  color: var(--color-primary) !important;
  box-shadow: 0 6px 20px rgba(184, 141, 53, 0.45) !important;
  transform: translateY(-1px);
}

.btn-outline {
  background: transparent;
  border: 1.5px solid var(--color-border);
  color: var(--color-text-muted);
  font-weight: 600;
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-md);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.btn-outline:hover {
  background: #F8FAFC;
  color: var(--color-primary);
  border-color: var(--color-primary);
}

/* Success Card */
.enquiry-success-card {
  background: #FFFFFF;
  border: 2px solid #86EFAC;
  border-radius: var(--radius-xl);
  padding: 3rem;
  box-shadow: var(--shadow-xl);
  text-align: center;
  animation: fadeIn 0.4s ease;
}

.success-icon-wrapper {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: #ECFDF5;
  color: #10B981;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem auto;
}

.success-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-primary);
  margin-bottom: 0.75rem;
}

.success-subtitle {
  font-size: 1.05rem;
  color: var(--color-text-muted);
  max-width: 600px;
  margin: 0 auto 2rem auto;
  line-height: 1.6;
}

.success-summary-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  background: #F8FAFC;
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  max-width: 650px;
  margin: 0 auto 2rem auto;
  text-align: left;
}

.summary-item {
  display: flex;
  justify-content: space-between;
  font-size: 0.875rem;
  padding-bottom: 0.4rem;
  border-bottom: 1px dashed var(--color-border);
}

.summary-lbl {
  color: var(--color-text-muted);
}

.summary-val {
  font-weight: 700;
  color: var(--color-primary);
}

.demo-notice-box {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  background: #FFFBEB;
  border: 1px solid #FDE68A;
  border-radius: var(--radius-md);
  padding: 1.25rem;
  max-width: 650px;
  margin: 0 auto 2rem auto;
  text-align: left;
  font-size: 0.85rem;
  color: #92400E;
}

.demo-notice-box .notice-icon {
  color: #D97706;
  flex-shrink: 0;
  margin-top: 0.15rem;
}

.phone-inline-link {
  color: #B45309;
  font-weight: 700;
  text-decoration: underline;
}

/* --------------------------------------------------------------------------
   7. Features Grid & Steps Grid
   -------------------------------------------------------------------------- */
.pl-why-us-section {
  padding: 5rem 0;
}

.pl-features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.75rem;
}

.pl-feature-card {
  background: #FFFFFF;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem 1.5rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-normal), box-shadow var(--transition-normal);
}

.pl-feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-card-hover);
  border-color: rgba(214, 173, 96, 0.4);
}

.feat-icon-box {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background-color: var(--color-secondary-tint);
  color: var(--color-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
}

.feat-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 0.75rem;
}

.feat-desc {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--color-text-muted);
}

/* How It Works Steps */
.pl-how-it-works-section {
  padding: 5rem 0;
  background-color: var(--color-bg);
}

.pl-steps-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.75rem;
}

.pl-step-card {
  background: #FFFFFF;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem 1.5rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-normal);
}

.pl-step-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.step-badge-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.25rem;
}

.step-counter {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-accent);
  font-family: var(--font-serif);
}

.step-icon-wrapper {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--color-secondary-tint);
  color: var(--color-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.step-heading {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 0.65rem;
}

.step-explanation {
  font-size: 0.875rem;
  line-height: 1.55;
  color: var(--color-text-muted);
}

/* --------------------------------------------------------------------------
   8. FAQs & Regulatory Disclaimer
   -------------------------------------------------------------------------- */
.pl-faq-section {
  padding: 5rem 0;
}

.pl-faq-callout {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 100%);
  color: #FFFFFF;
  border-radius: var(--radius-lg);
  padding: 1.75rem 2rem;
  margin-top: 3rem;
  flex-wrap: wrap;
}

.pl-faq-callout .callout-icon {
  color: var(--color-accent-light);
  flex-shrink: 0;
}

.callout-text {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.callout-text strong {
  font-size: 1rem;
  color: #FFFFFF;
}

.callout-text span {
  font-size: 0.85rem;
  color: #CBD5E1;
}

/* Mandatory Disclaimer */
.pl-disclaimer-section {
  padding: 3rem 0 5rem 0;
  background-color: var(--color-bg);
}

.pl-mandatory-disclaimer-card {
  background: #FFFFFF;
  border: 1px solid rgba(214, 173, 96, 0.4);
  border-left: 5px solid var(--color-accent);
  border-radius: var(--radius-lg);
  padding: 2rem 2.25rem;
  box-shadow: var(--shadow-sm);
}

.disclaimer-header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin-bottom: 0.85rem;
}

.disclaimer-icon {
  color: var(--color-accent-dark);
}

.disclaimer-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-primary);
  margin: 0;
}

.disclaimer-body {
  font-size: 0.9rem;
  line-height: 1.65;
  color: var(--color-text-muted);
  margin-bottom: 1.25rem;
}

.disclaimer-footer-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.8rem;
  color: var(--color-text-light);
  padding-top: 1rem;
  border-top: 1px solid var(--color-border-subtle);
  flex-wrap: wrap;
}

.btn-back-services-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  background: none;
  border: none;
  color: var(--color-secondary);
  font-weight: 700;
  font-size: 0.85rem;
  cursor: pointer;
  padding: 0;
  transition: color var(--transition-fast);
}

.btn-back-services-link:hover {
  color: var(--color-primary);
  text-decoration: underline;
}

/* --------------------------------------------------------------------------
   9. Responsive Breakpoints
   -------------------------------------------------------------------------- */
@media (max-width: 1024px) {
  .pl-hero-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .calculator-layout-card {
    grid-template-columns: 1fr;
    padding: 2rem;
  }

  .pl-features-grid,
  .pl-steps-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .calculator-layout-card {
    padding: 1.5rem;
  }

  .enquiry-form-card {
    padding: 1.5rem;
  }

  .form-grid-2col {
    grid-template-columns: 1fr;
  }

  .form-group-span-2 {
    grid-column: span 1;
  }

  .radio-pill-group {
    grid-template-columns: 1fr;
  }

  .pl-features-grid,
  .pl-steps-grid {
    grid-template-columns: 1fr;
  }

  .emi-chart-wrapper {
    flex-direction: column;
  }

  .summary-metrics-grid {
    grid-template-columns: 1fr;
  }

  .success-summary-grid {
    grid-template-columns: 1fr;
  }

  .pl-hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .pl-hero-btn-primary,
  .pl-hero-btn-secondary {
    width: 100%;
    justify-content: center;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  .visual-card-glass,
  .pl-feature-card,
  .pl-step-card,
  .metric-box,
  .chart-circle-principal,
  .chart-circle-interest {
    transition: none !important;
    animation: none !important;
    transform: none !important;
  }
}

/* ==========================================================================
   PERSONAL LOAN ENQUIRY — SIDE-BY-SIDE GRID & INTEGRATED CALCULATOR
   ========================================================================== */
.pl-enquiry-hero {
  padding: 3.5rem 0 4.5rem 0;
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 55%, var(--color-primary-light) 100%);
  color: var(--color-white);
  position: relative;
  overflow: hidden;
}

/* Background Design Decor Layer (Royal Navy + Gold Theme) */
.pl-enquiry-bg-decor {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 1;
}

/* 1. Subtle Gold Constellation Dot-Grid Pattern */
.pl-enquiry-dot-grid {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: radial-gradient(rgba(212, 168, 79, 0.16) 1.2px, transparent 1.2px);
  background-size: 28px 28px;
  mask-image: radial-gradient(ellipse at 75% 50%, black 40%, transparent 80%);
  -webkit-mask-image: radial-gradient(ellipse at 75% 50%, black 40%, transparent 80%);
  opacity: 0.85;
}

/* 2. Ambient Radial Glowing Orbs (Gold and Deep Navy) */
.pl-enquiry-ambient-orb-1 {
  position: absolute;
  top: -120px;
  right: -80px;
  width: 580px;
  height: 580px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212, 168, 79, 0.18) 0%, rgba(16, 42, 67, 0) 70%);
  filter: blur(55px);
}

.pl-enquiry-ambient-orb-2 {
  position: absolute;
  bottom: -150px;
  left: -80px;
  width: 480px;
  height: 480px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(29, 61, 94, 0.45) 0%, transparent 70%);
  filter: blur(45px);
}

/* 3. Concentric Luxury Geometric Rings (Gold & Navy) */
.pl-enquiry-concentric-rings {
  position: absolute;
  top: 50%;
  right: 8%;
  transform: translateY(-50%);
  width: 440px;
  height: 440px;
  pointer-events: none;
}

.pl-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
}

.pl-ring-outer {
  width: 440px;
  height: 440px;
  border: 1.5px solid rgba(212, 168, 79, 0.14);
}

.pl-ring-middle {
  width: 320px;
  height: 320px;
  border: 1.5px dashed rgba(212, 168, 79, 0.22);
  animation: rotatePlRings 60s linear infinite;
}

.pl-ring-inner {
  width: 200px;
  height: 200px;
  border: 1px solid rgba(212, 168, 79, 0.28);
  background: radial-gradient(circle, rgba(212, 168, 79, 0.08) 0%, transparent 75%);
}

@keyframes rotatePlRings {
  from {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  to {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

/* 4. Subtle Floating Gold Sparkles */
.pl-decor-diamond {
  position: absolute;
  width: 10px;
  height: 10px;
  background-color: var(--color-accent);
  transform: rotate(45deg);
  opacity: 0.35;
  filter: drop-shadow(0 0 8px rgba(212, 168, 79, 0.8));
}

.pl-diamond-1 {
  top: 25%;
  right: 36%;
  animation: pulsePlDiamond 4s ease-in-out infinite;
}

.pl-diamond-2 {
  bottom: 22%;
  right: 12%;
  width: 8px;
  height: 8px;
  opacity: 0.45;
  animation: pulsePlDiamond 5s ease-in-out infinite 1.5s;
}

.pl-diamond-3 {
  top: 18%;
  right: 15%;
  width: 6px;
  height: 6px;
  opacity: 0.3;
  animation: pulsePlDiamond 6s ease-in-out infinite 0.7s;
}

@keyframes pulsePlDiamond {
  0%, 100% {
    transform: rotate(45deg) scale(1);
    opacity: 0.3;
  }
  50% {
    transform: rotate(45deg) scale(1.35);
    opacity: 0.65;
  }
}

.pl-enquiry-hero-container {
  position: relative;
  z-index: 2;
}

.pl-enquiry-hero-grid {
  display: grid;
  grid-template-columns: 1.25fr 0.85fr;
  align-items: center;
  gap: 3.5rem;
}

.pl-enquiry-header-box {
  max-width: 720px;
}

/* Right Side Floating Visual Cards in Royal Navy + Gold */
.pl-enquiry-hero-visual {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

.pl-hero-stat-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid rgba(212, 168, 79, 0.28);
  border-radius: var(--radius-lg);
  padding: 1.15rem 1.4rem;
  box-shadow: 0 10px 25px -5px rgba(10, 28, 46, 0.4), 0 0 15px -3px rgba(212, 168, 79, 0.12);
  transition: transform var(--transition-normal), border-color var(--transition-normal), box-shadow var(--transition-normal);
}

.pl-hero-stat-card:hover {
  transform: translateY(-3px) translateX(4px);
  border-color: rgba(212, 168, 79, 0.55);
  box-shadow: 0 14px 30px -5px rgba(10, 28, 46, 0.5), 0 0 20px 0 rgba(212, 168, 79, 0.25);
}

.pl-stat-card-1 {
