}

@keyframes floatSubtle1 {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

@keyframes floatSubtle2 {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(4px); }
}

.pl-stat-icon-wrap {
  width: 44px;
  height: 44px;
