  background: rgba(212, 168, 79, 0.15);
  border: 1px solid rgba(212, 168, 79, 0.35);
  color: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-shadow: 0 4px 12px rgba(212, 168, 79, 0.15);
}

.pl-stat-info {
  display: flex;
  flex-direction: column;
}

.pl-stat-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: #FFFFFF;
  margin-bottom: 0.15rem;
}

.pl-stat-sub {
  font-size: 0.825rem;
  color: #CBD5E1;
  line-height: 1.4;
}

@media (max-width: 992px) {
  .pl-enquiry-hero-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .pl-enquiry-hero-visual {
    display: none;
  }
  .pl-enquiry-concentric-rings {
    display: none;
  }
}

.pl-enquiry-main-title {
  font-size: clamp(2.2rem, 4.5vw, 3.4rem);
