m;\n  resize: vertical;\n}\n\n/* Radio Pill Group */\n.radio-pill-group {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 0.75rem;\n}\n\n.radio-pill-item {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n  padding: 0.75rem 1rem;\n  background-color: #F8FAFC;\n  border: 1.5px solid var(--color-border);\n  border-radius: var(--radius-md);\n  font-size: 0.9rem;\n  font-weight: 600;\n  color: var(--color-text-muted);\n  cursor: pointer;\n  transition: all var(--transition-fast);\n}\n\n.radio-pill-item:hover {\n  border-color: var(--color-secondary);\n  color: var(--color-primary);\n}\n\n.radio-pill-item.is-selected {\n  background-color: var(--color-secondary-tint);\n  border-color: var(--color-secondary);\n  color: var(--color-secondary);\n  font-weight: 700;\n}\n\n/* Preferred Contact Method Pills */\n.contact-methods-pill-group {\n  display: flex;\n  gap: 0.75rem;\n  flex-wrap: wrap;\n}\n\n.method-pill-item {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n  padding: 0.6rem 1.25rem;\n  background-color: #F8FAFC;\n  border: 1.5px solid var(--color-border);\n  border-radius: var(--radius-full);\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: var(--color-text-muted);\n  cursor: pointer;\n  transition: all var(--transition-fast);\n}\n\n.method-pill-item:hover {\n  border-color: var(--color-secondary);\n  color: var(--color-primary);\n}\n\n.method-pill-item.is-selected {\n  background-color: var(--color-primary);\n  border-color: var(--color-primary);\n  color: #FFFFFF;\n}\n\n.form-error-msg {\n  display: flex;\n  align-items: center;\n  gap: 0.35rem;\n  font-size: 0.775rem;\n  color: var(--color-error);\n  margin-top: 0.35rem;\n  animation: fadeIn 0.2s ease;\n}\n\n.form-privacy-note {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  font-size: 0.8rem;\n  color: var(--color-text-muted);\n  margin-top: 1.5rem;\n  padding: 0.85rem 1rem;\n  background-color: #F8FAFC;\n  border-radius: var(--radius-md);\n}\n\n.shield-icon {\n  color: var(--color-secondary);\n  flex-shrink: 0;\n}\n\n.form-actions-row {\n  display: flex;\n  align-items: center;\n  gap: 1rem;\n  margin-top: 2rem;\n  flex-wrap: wrap;\n}\n\n.submit-enquiry-btn {\n  flex-grow: 1;\n  justify-content: center;\n  background: var(--color-accent) !important;\n  color: var(--color-primary) !important;\n  font-weight: 700 !important;\n  box-shadow: 0 4px 14px rgba(212, 168, 79, 0.35) !important;\n  border: none !important;\n  transition: all var(--transition-fast);\n}\n\n.submit-enquiry-btn:hover {\n  background: var(--color-accent-dark) !important;\n  color: var(--color-primary) !important;\n  box-shadow: 0 6px 20px rgba(184, 141, 53, 0.45) !important;\n  transform: translateY(-1px);\n}\n\n.btn-outline {\n  background: transparent;\n  border: 1.5px solid var(--color-border);\n  color: var(--color-text-muted);\n  font-weight: 600;\n  padding: 0.75rem 1.25rem;\n  border-radius: var(--radius-md);\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  cursor: pointer;\n  transition: all var(--transition-fast);\n}\n\n.btn-outline:hover {\n  background: #F8FAFC;\n  color: var(--color-primary);\n  border-color: var(--color-primary);\n}\n\n/* Success Card */\n.enquiry-success-card {\n  background: #FFFFFF;\n  border: 2px solid #86EFAC;\n  border-radius: var(--radius-xl);\n  padding: 3rem;\n  box-shadow: var(--shadow-xl);\n  text-align: center;\n  animation: fadeIn 0.4s ease;\n}\n\n.success-icon-wrapper {\n  width: 72px;\n  height: 72px;\n  border-radius: 50%;\n  background: #ECFDF5;\n  color: #10B981;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin: 0 auto 1.5rem auto;\n}\n\n.success-title {\n  font-size: 1.75rem;\n  font-weight: 800;\n  color: var(--color-primary);\n  margin-bottom: 0.75rem;\n}\n\n.success-subtitle {\n  font-size: 1.05rem;\n  color: var(--color-text-muted);\n  max-width: 600px;\n  margin: 0 auto 2rem auto;\n  line-height: 1.6;\n}\n\n.success-summary-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 1rem;\n  background: #F8FAFC;\n  border-radius: var(--radius-lg);\n  padding: 1.5rem;\n  max-width: 650px;\n  margin: 0 auto 2rem auto;\n  text-align: left;\n}\n\n.summary-item {\n  display: flex;\n  justify-content: space-between;\n  font-size: 0.875rem;\n  padding-bottom: 0.4rem;\n  border-bottom: 1px dashed var(--color-border);\n}\n\n.summary-lbl {\n  color: var(--color-text-muted);\n}\n\n.summary-val {\n  font-weight: 700;\n  color: var(--color-primary);\n}\n\n.demo-notice-box {\n  display: flex;\n  align-items: flex-start;\n  gap: 1rem;\n  background: #FFFBEB;\n  border: 1px solid #FDE68A;\n  border-radius: var(--radius-md);\n  padding: 1.25rem;\n  max-width: 650px;\n  margin: 0 auto 2rem auto;\n  text-align: left;\n  font-size: 0.85rem;\n  color: #92400E;\n}\n\n.demo-notice-box .notice-icon {\n  color: #D97706;\n  flex-shrink: 0;\n  margin-top: 0.15rem;\n}\n\n.phone-inline-link {\n  color: #B45309;\n  font-weight: 700;\n  text-decoration: underline;\n}\n\n/* --------------------------------------------------------------------------\n   7. Features Grid & Steps Grid\n   -------------------------------------------------------------------------- */\n.pl-why-us-section {\n  padding: 5rem 0;\n}\n\n.pl-features-grid {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 1.75rem;\n}\n\n.pl-feature-card {\n  background: #FFFFFF;\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-lg);\n  padding: 2rem 1.5rem;\n  box-shadow: var(--shadow-sm);\n  display: flex;\n  flex-direction: column;\n  transition: transform var(--transition-normal), box-shadow var(--transition-normal);\n}\n\n.pl-feature-card:hover {\n  transform: translateY(-4px);\n  box-shadow: var(--shadow-card-hover);\n  border-color: rgba(214, 173, 96, 0.4);\n}\n\n.feat-icon-box {\n  width: 48px;\n  height: 48px;\n  border-radius: var(--radius-md);\n  background-color: var(--color-secondary-tint);\n  color: var(--color-secondary);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin-bottom: 1.25rem;\n}\n\n.feat-title {\n  font-size: 1.1rem;\n  font-weight: 700;\n  color: var(--color-primary);\n  margin-bottom: 0.75rem;\n}\n\n.feat-desc {\n  font-size: 0.9rem;\n  line-height: 1.6;\n  color: var(--color-text-muted);\n}\n\n/* How It Works Steps */\n.pl-how-it-works-section {\n  padding: 5rem 0;\n  background-color: var(--color-bg);\n}\n\n.pl-steps-grid {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 1.75rem;\n}\n\n.pl-step-card {\n  background: #FFFFFF;\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-lg);\n  padding: 2rem 1.5rem;\n  box-shadow: var(--shadow-sm);\n  display: flex;\n  flex-direction: column;\n  transition: transform var(--transition-normal);\n}\n\n.pl-step-card:hover {\n  transform: translateY(-4px);\n  box-shadow: var(--shadow-md);\n}\n\n.step-badge-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 1.25rem;\n}\n\n.step-counter {\n  font-size: 1.75rem;\n  font-weight: 800;\n  color: var(--color-accent);\n  font-family: var(--font-serif);\n}\n\n.step-icon-wrapper {\n  width: 40px;\n  height: 40px;\n  border-radius: var(--radius-md);\n  background: var(--color-secondary-tint);\n  color: var(--color-secondary);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.step-heading {\n  font-size: 1.1rem;\n  font-weight: 700;\n  color: var(--color-primary);\n  margin-bottom: 0.65rem;\n}\n\n.step-explanation {\n  font-size: 0.875rem;\n  line-height: 1.55;\n  color: var(--color-text-muted);\n}\n\n/* --------------------------------------------------------------------------\n   8. FAQs & Regulatory Disclaimer\n   -------------------------------------------------------------------------- */\n.pl-faq-section {\n  padding: 5rem 0;\n}\n\n.pl-faq-callout {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1.5rem;\n  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 100%);\n  color: #FFFFFF;\n  border-radius: var(--radius-lg);\n  padding: 1.75rem 2rem;\n  margin-top: 3rem;\n  flex-wrap: wrap;\n}\n\n.pl-faq-callout .callout-icon {\n  color: var(--color-accent-light);\n  flex-shrink: 0;\n}\n\n.callout-text {\n  display: flex;\n  flex-direction: column;\n  flex-grow: 1;\n}\n\n.callout-text strong {\n  font-size: 1rem;\n  color: #FFFFFF;\n}\n\n.callout-text span {\n  font-size: 0.85rem;\n  color: #CBD5E1;\n}\n\n/* Mandatory Disclaimer */\n.pl-disclaimer-section {\n  padding: 3rem 0 5rem 0;\n  background-color: var(--color-bg);\n}\n\n.pl-mandatory-disclaimer-card {\n  background: #FFFFFF;\n  border: 1px solid rgba(214, 173, 96, 0.4);\n  border-left: 5px solid var(--color-accent);\n  border-radius: var(--radius-lg);\n  padding: 2rem 2.25rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.disclaimer-header {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  margin-bottom: 0.85rem;\n}\n\n.disclaimer-icon {\n  color: var(--color-accent-dark);\n}\n\n.disclaimer-title {\n  font-size: 1.05rem;\n  font-weight: 700;\n  color: var(--color-primary);\n  margin: 0;\n}\n\n.disclaimer-body {\n  font-size: 0.9rem;\n  line-height: 1.65;\n  color: var(--color-text-muted);\n  margin-bottom: 1.25rem;\n}\n\n.disclaimer-footer-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  font-size: 0.8rem;\n  color: var(--color-text-light);\n  padding-top: 1rem;\n  border-top: 1px solid var(--color-border-subtle);\n  flex-wrap: wrap;\n}\n\n.btn-back-services-link {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n  background: none;\n  border: none;\n  color: var(--color-secondary);\n  font-weight: 700;\n  font-size: 0.85rem;\n  cursor: pointer;\n  padding: 0;\n  transition: color var(--transition-fast);\n}\n\n.btn-back-services-link:hover {\n  color: var(--color-primary);\n  text-decoration: underline;\n}\n\n/* --------------------------------------------------------------------------\n   9. Responsive Breakpoints\n   -------------------------------------------------------------------------- */\n@media (max-width: 1024px) {\n  .pl-hero-grid {\n    grid-template-columns: 1fr;\n    gap: 2.5rem;\n  }\n\n  .calculator-layout-card {\n    grid-template-columns: 1fr;\n    padding: 2rem;\n  }\n\n  .pl-features-grid,\n  .pl-steps-grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n\n@media (max-width: 768px) {\n  .calculator-layout-card {\n    padding: 1.5rem;\n  }\n\n  .enquiry-form-card {\n    padding: 1.5rem;\n  }\n\n  .form-grid-2col {\n    grid-template-columns: 1fr;\n  }\n\n  .form-group-span-2 {\n    grid-column: span 1;\n  }\n\n  .radio-pill-group {\n    grid-template-columns: 1fr;\n  }\n\n  .pl-features-grid,\n  .pl-steps-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .emi-chart-wrapper {\n    flex-direction: column;\n  }\n\n  .summary-metrics-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .success-summary-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .pl-hero-actions {\n    flex-direction: column;\n    align-items: stretch;\n  }\n\n  .pl-hero-btn-primary,\n  .pl-hero-btn-secondary {\n    width: 100%;\n    justify-content: center;\n  }\n}\n\n/* Reduced Motion */\n@media (prefers-reduced-motion: reduce) {\n  .visual-card-glass,\n  .pl-feature-card,\n  .pl-step-card,\n  .metric-box,\n  .chart-circle-principal,\n  .chart-circle-interest {\n    transition: none !important;\n    animation: none !important;\n    transform: none !important;\n  }\n}\n\n/* ==========================================================================\n   PERSONAL LOAN ENQUIRY — SIDE-BY-SIDE GRID & INTEGRATED CALCULATOR\n   ========================================================================== */\n.pl-enquiry-hero {\n  padding: 3.5rem 0 4.5rem 0;\n  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 55%, var(-